MOD = 1000000007

def count_paths(n, k, d):
    # dp[i][j] will store the number of paths of total weight i ending at a node with weight j
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: There's one way to have a path of weight 0 (doing nothing)
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for w in range(1, k + 1):
                if i >= w:
                    dp[i][j] = (dp[i][j] + dp[i - w][w]) % MOD

    # Calculate the total number of paths of weight n
    total_paths = sum(dp[n]) % MOD

    # Calculate the number of paths of weight n without any edge of weight at least d
    paths_without_d = 0
    for i in range(1, d):
        for j in range(1, k + 1):
            for w in range(1, k + 1):
                if w < d and i >= w:
                    paths_without_d = (paths_without_d + dp[i - w][w]) % MOD

    # The result is the total paths minus the paths without any edge of weight at least d
    return (total_paths - paths_without_d + MOD) % MOD

# Read input
n, k, d = map(int, input().split())

# Output the result
print(count_paths(n, k, d))
